const body = $('Webhook').first().json.body;
const priceRows = $input.all().map(i => i.json);

// мапа: variant_id -> ціна товару
const priceByVariant = Object.fromEntries(
  priceRows.map(r => [r.id, r.products.price])
);

const items = body.items.map(i => {
  const price = priceByVariant[i.variant_id];
  // варіанта немає в базі — краще впасти зараз, ніж записати кривий чек
  if (price === undefined) throw new Error(`Unknown variant: ${i.variant_id}`);
  if (!Number.isInteger(i.quantity) || i.quantity < 1) throw new Error(`Bad quantity for variant ${i.variant_id}`);

  return {
    variant_id: i.variant_id,
    quantity: i.quantity,
    price_at_purchase: price      // ціна з БАЗИ, не зі сторінки
  };
});

const total = items.reduce((sum, i) => sum + i.price_at_purchase * i.quantity, 0);

return [{
  json: {
    customer: body.customer,
    items,
    total: Math.round(total * 100) / 100   // до копійок
  }
}];

const orderId = $input.first().json.id;          // id щойно створеного замовлення
const items = $('Build order').first().json.items;

const rows = items.map(i => ({
  order_id: orderId,
  variant_id: i.variant_id,
  quantity: i.quantity,
  price_at_purchase: i.price_at_purchase
}));

return [{ json: { rows, order_id: orderId } }];

const raw = $input.first().json;
const msg = raw.error?.message || raw.message || JSON.stringify(raw);
const details = raw.error?.details || raw.details || "";
const full = msg + " " + details;

let reason = "server_error";
let message = "We couldn't place the order. Please try again.";

if (/Not enough stock/i.test(full)){
  reason = "out_of_stock";
  message = "Some items are no longer available in that quantity. Please adjust your cart.";
} else if (/Unknown variant/i.test(full)){
  reason = "unknown_variant";
  message = "One of the items is no longer in the catalogue.";
} else if (/Empty order/i.test(full)){
  reason = "empty_order";
  message = "Your cart is empty.";
} else if (/orders_phone_format/i.test(full)){
  reason = "invalid_phone";
  message = "That phone number doesn't match the selected country.";
} else if (/orders_postcode_format/i.test(full)){
  reason = "invalid_postcode";
  message = "That postcode doesn't match the selected country.";
} else if (/orders_country_allowed/i.test(full)){
  reason = "invalid_country";
  message = "We don't deliver to that country yet.";
} else if (/violates not-null constraint|null value in column/i.test(full)){
  reason = "missing_field";
  message = "Some delivery details are missing. Please check the form.";
}

return [{ json: { ok: false, reason, message } }];
